void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec3 trail = texture(iChannel0, uv).rgb;
    vec3 col = trail * trail * 1.4 + vec3(0.02, 0.01, 0.05);
    fragColor = vec4(col, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec2 c = uv - 0.5;
    vec2 back = rotate2(c, 0.02) * 0.985 + 0.5;
    vec3 prev = texture(iChannel0, back).rgb * TRAIL;
    vec2 orbit = 0.28 * vec2(cos(iTime * 1.3), sin(iTime * 1.7));
    float dot_ = smoothstep(0.05, 0.0, distance(c, orbit));
    fragColor = vec4(prev + dot_ * vec3(0.9, 0.35, 0.55), 1.0);
}

const float TRAIL = 0.94;

vec2 rotate2(vec2 v, float a)
{
    return vec2(cos(a) * v.x - sin(a) * v.y, sin(a) * v.x + cos(a) * v.y);
}
